package com.netranews.model;
import java.time.Instant; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document;
@Document("comments") public class Comment { @Id private String id; private String newsId; private String userEmail; private String userName; private String text; private Instant createdAt=Instant.now(); public String getId(){return id;} public String getNewsId(){return newsId;} public void setNewsId(String v){newsId=v;} public String getUserEmail(){return userEmail;} public void setUserEmail(String v){userEmail=v;} public String getUserName(){return userName;} public void setUserName(String v){userName=v;} public String getText(){return text;} public void setText(String v){text=v;} public Instant getCreatedAt(){return createdAt;} }
